WITH f AS (
  SELECT patient, event AS d, lower(json_extract(payload,'$.drug_name')) AS drug FROM (SELECT * FROM records WHERE stream='payer_pharmacy_claims' AND id NOT IN (SELECT supersedes FROM records WHERE stream='payer_pharmacy_claims' AND supersedes IS NOT NULL))
  WHERE json_extract(payload,'$.claim_status') = 'paid' AND (lower(json_extract(payload,'$.drug_name')) LIKE '%metformin%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%semaglutide%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%ozempic%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%wegovy%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%rybelsus%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%dulaglutide%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%trulicity%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%liraglutide%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%victoza%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%tirzepatide%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%mounjaro%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%empagliflozin%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%jardiance%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%dapagliflozin%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%farxiga%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%canagliflozin%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%sitagliptin%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%januvia%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%linagliptin%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%glipizide%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%glimepiride%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%glyburide%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%pioglitazone%' OR lower(json_extract(payload,'$.drug_name')) LIKE '%insulin%')
  UNION
  SELECT patient, event, lower(json_extract(payload,'$.medication_name')) FROM records
  WHERE stream = 'pharmacy_dispenses' AND json_extract(payload,'$.status') = 'dispensed' AND (lower(json_extract(payload,'$.medication_name')) LIKE '%metformin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%semaglutide%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%ozempic%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%wegovy%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%rybelsus%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%dulaglutide%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%trulicity%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%liraglutide%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%victoza%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%tirzepatide%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%mounjaro%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%empagliflozin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%jardiance%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%dapagliflozin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%farxiga%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%canagliflozin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%sitagliptin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%januvia%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%linagliptin%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%glipizide%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%glimepiride%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%glyburide%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%pioglitazone%' OR lower(json_extract(payload,'$.medication_name')) LIKE '%insulin%')
),
c AS (SELECT patient, d, CASE WHEN drug LIKE '%metformin%' THEN 'met' ELSE 'other' END AS cls FROM f),
met1 AS (SELECT patient, MIN(d) AS m FROM c WHERE cls = 'met' GROUP BY patient),
oth1 AS (SELECT patient, MIN(d) AS o FROM c WHERE cls = 'other' GROUP BY patient),
l2 AS (SELECT met1.patient, met1.m, oth1.o FROM met1 JOIN oth1 ON oth1.patient = met1.patient WHERE oth1.o > met1.m)
SELECT ROUND(AVG(julianday(o) - julianday(m)), 1) AS value FROM l2
